BEGIN;
SELECT ('30000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'R-'||(1000+n),('10000000-0000-0000-0000-'||lpad((CASE WHEN n>6 THEN 2 ELSE 1 END)::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad((1+n%3)::text,12,'0'))::uuid,
 (ARRAY['iPhone 13','ThinkPad T14','iPad Air'])[1+n%3],'DEMO-'||n,(ARRAY['Cracked display','Battery fails load test','Charging socket intermittent'])[1+n%3],(ARRAY['Jo','Ravi'])[1+n%2],(ARRAY['assessment','approved','repairing','parts','ready','collected','repairing','ready','parts'])[n],now()-interval '16 days',CASE WHEN n<>1 THEN now()-interval '15 days' END,current_date+(n-6),CASE WHEN n IN (5,6,8) THEN now()-interval '9 days' END,now()-interval '8 days',18000+n*1000,18000+n*1000,CASE WHEN n=6 THEN 24000 ELSE 5000 END,CASE WHEN n<>7 THEN 'Signed quote Q-'||n END,'Scuffs on frame',CASE WHEN n IN (5,6,8) THEN 'Display, charging and speaker checks passed' END,CASE WHEN n IN (5,6,8) THEN 'Jo' END,current_date+30 FROM generate_series(1,9)n ON CONFLICT DO NOTHING;
COMMIT;
